  },
  "criteria": {
    "definition": {
      "assessment": "sufficient",
      "reason": "说明了空间处理为何属于模型函数，定义请求身份、processor、权重、任务输出、逻辑张量与地址单位，并区分逻辑状态和物理完成。卷积采用互相关定义，几何、池化和检测坐标的轴与约定可核算。",
      "evidence": [
        {
          "path": "knowledge/models/vision-inference.md",
          "quote": "设一个请求为 q=(id,g,S,P,M,T)，其中 id 是请求身份，g 是本次执行尝试，S 是不可变图像快照，P 是 processor 契约，M 是模型与权重身份，T 是任务头与后处理契约。"
        },
        {
          "path": "knowledge/models/vision-inference.md",
          "quote": "状态表示逻辑责任，不等同于设备 DMA 或 kernel 已完成。"
        }
      ]
    },
    "legality": {
      "assessment": "sufficient",
      "reason": "当前正文正确区分模型输入填充、卷积算子边界和执行器额外槽。固定[1,0]的普通平均必须为1/2；源像素掩码和物理容量分母分别产生1和1/4，均被识别为改变函数。两层边界回流反例进一步否定末端屏蔽的通用充分性。组参数、BN折叠、残差存活、NMS顺序及数值等价条件也已明确。K-MODEL-014-R1-L01可关闭；完整候选复核未发现需要保留的campaign阻断问题。",
      "evidence": [
        {
          "path": "knowledge/models/vision-inference.md",
          "quote": "checkpoint 原本在整个特征图上做全局平均池化，就应保留那个域及分母；若模型明确规定 masked pooling，才按它的掩码规则执行。"
        },
        {
          "path": "knowledge/models/vision-inference.md",
          "quote": "特别地，执行有效域包含 P 原本规定的 padding，不能把源图像区域掩码直接当作执行掩码。"
        },
        {
          "path": "knowledge/models/vision-inference.md",
          "quote": "合法改写要求在声明输入域内 R(F̂(E(X))) 与 F(X) 满足规定的数学或数值关系。这个条件包含全部层、统计域、坐标和输出身份。"
        }
      ]
    },
    "algorithm": {
      "assessment": "sufficient",
      "reason": "预处理、分组卷积、窗口到矩阵的下标解码、tile归约及交接、固定BN折叠、残差和NMS均给出可恢复的数据流。卷积边界检查先于读取，bias和非线性位于完整归约之后。两层示例明确追踪上一层输出如何成为下一层输入，并限定逐层隔离的成立条件。",
      "evidence": [
        {
          "path": "knowledge/models/vision-inference.md",
          "quote": "正确性不变量是：输出位置只归约声明感受野中的输入；输入与输出通道属于同一组；bias 对每个输出恰好加一次；边界判断先于读取。"
        },
        {
          "path": "knowledge/models/vision-inference.md",
          "quote": "协作实现须等待本阶段全部输入对消费者可见"
        },
        {
          "path": "knowledge/models/vision-inference.md",
          "quote": "本阶段所有读取结束后才允许覆盖输入 tile"
        },
        {
          "path": "knowledge/models/vision-inference.md",
          "quote": "执行器扩到 [1,0] 后，第一层得到 [1,1]，额外位置已吸收原输入；第二层得到 [2,2]，额外位置的值又传播回原位置。"
        }
      ]
    },
    "cost": {
      "assessment": "sufficient",
      "reason": "卷积MAC、权重和展开容量推导正确，C12-C的115605504 MAC、401408输出字节及3612672展开字节可复算。逐组峰值与全部组总交通分开，tile和split-K成本给出元素字节口径。六类成本、额外槽实际计算、准备摊销和关键路径均有条件说明，没有把逻辑字节或算术量当成设备实测。",
      "evidence": [
        {
          "path": "knowledge/models/vision-inference.md",
          "quote": "若一次物化全部组，展开元素总数为 B·Hout·Wout·Cin·Kh·Kw；若逐组物化，峰值可降为 B·Hout·Wout·(Cin/G)·Kh·Kw，总写读与所有组的计算仍要列账。"
        },
        {
          "path": "knowledge/models/vision-inference.md",
          "quote": "成本应分阶段列账：解码和重采样是主机计算；布局转换与 H2D 是访存/通信；卷积包括乘加、权重读取、片上驻留和协作同步；NMS 随候选变化；等待聚批是队列成本；编译、调优和权重打包是准备成本。"
        },
        {
          "path": "knowledge/models/vision-inference.md",
          "quote": "端到端时间由依赖关键路径与共享资源决定，不能把可重叠阶段耗时直接相加。"
        }
      ]
    },
    "adaptation": {
      "assessment": "sufficient",
      "reason": "说明了shape、桶容量、统计方式、精度、片上资源、复用次数及候选规模改变后的重新判断。保留模型输入契约和逐层依赖，调整tile、融合及域隔离；证明不足时回退。降低分辨率或改depthwise被明确视作函数或质量条件变化。",
      "evidence": [
        {
          "path": "knowledge/models/vision-inference.md",
          "quote": "片上资源不足时应缩小 tile、改变融合边界或放弃该映射。"
        },
        {
          "path": "knowledge/models/vision-inference.md",
          "quote": "一般网络还要按实际 stride、padding、dilation、pooling 和分支推导每层逻辑域及边界规则，不能始终沿用输入掩码。"
        },
        {
          "path": "knowledge/models/vision-inference.md",
          "quote": "若未证明等价，可保留同完整逻辑 shape 聚批，或回退独立执行；不能把 masked pooling 当作通用修复。"
        }
      ]
    },
    "diagnosis": {
      "assessment": "sufficient",
      "reason": "诊断表对预处理、组索引、采样间距、边界传播、残差覆盖、BN及NMS提出不同预测，并指向首次分歧和单条件干预。检查脚本具有不同组织的参考和实际错误路径；所供执行记录显示相关负对照被比较器拒绝。正文明确区分机制验证与设备、质量和性能验证。",
      "evidence": [
        {
          "path": "knowledge/models/vision-inference.md",
          "quote": "保持完整 processor 输出不变，只改桶容量；逐层比较原逻辑域与额外域。末端分母错只解释归约差异，第二层边缘已错则必须修全链路边界或回退"
        },
        {
          "path": "knowledge/models/vision-inference.md",
          "quote": "padding 检查应把错误的源像素池化和仅末端屏蔽路径真正执行后交给同一比较器拒绝；仅检查存在掩码或输出 shape 相同没有判别力。"
        }
      ]
    }
  },
  "findings": [],
  "limitations": [
    "检查域为确定性整数、有理数和顺序小模型；不验证图像解码、实际插值、归一化、量化、非连续物理stride或完整checkpoint。",
    "逐层隔离枚举仅覆盖固定宽度、stride=1、零边界的一维两层卷积；不证明变尺寸层、动态统计、真实分支及任意池化的桶改写等价。",
    "BN检查仅验证给定平方根分母下的仿射关系；未执行完整参数合法性、平方根计算或目标dtype舍入。NMS有理数用例不验证NaN、Inf处理。",
    "tile、split-K及资源账主要由正文推导支持；脚本没有执行目标矩阵指令、异步完成协议或实际设备交通与性能测量，也没有任务质量和Agent使用效果证据。",
    "来源核对限于所供完整提取文本；未核验PDF图版、reader页面或本地链接目标实际存在。未读取上游源码。",
    "执行结论来自所供、绑定本轮脚本哈希的actual_preflight记录；本审阅调用未另行运行Python或访问本地文件。"
  ],
  "checks": [
    {
      "script": "tools/check_k_model_014_full.py",
      "args": []
    }
  ],
  "no_checks_reason": "",
  "reading_scope": "本审阅完整阅读所供AGENTS.md[0,567)、docs/knowledge-method.md[0,2251)、docs/knowledge-review.md[0,3016)、候选knowledge/models/vision-inference.md[0,14909)、knowledge/sources/S-RESNET.md[0,634)、S-TVM.md[0,609)、S-TORCH-NUMERIC.md[0,532)，以及references/S-RESNET/fulltext.txt[0,59678)、S-TVM/fulltext.txt[0,67763)、S-TORCH-NUMERIC/fulltext.txt[0,10998)。完整阅读所供检查脚本、author_notes及actual_preflight执行记录。相关章节只阅读供应摘录：operator-primitives.md[0,4142)、[8000,16000)；compile-dynamic-shapes.md[0,8576)、[16000,19566)；precision-and-kernel-support.md[0,4783)、[8000,15359)；host-runtime.md[0,10746)、[16000,17396)；vision-language.md[0,8239)、[12000,15903)；correctness-oracles.md[0,12142)；design-synthesis.md[0,4000)、[8000,8844)、[12000,19298)。范围单位均为供应提取文本的零基半开字符区间，摘录文件未列入documents。作者材料账与本审阅阅读范围分开：作者账记录原正文a3b95c24…及三份完整来源原文和指定相关摘录的供应范围，不据此证明作者实际认知阅读；本次判断绑定候选ec3475b7…，不把原正文哈希混作本轮候选身份。",
  "test_assessment": "已逐函数检查脚本及所供真实执行。conv_gather按输出归约，conv_scatter_reference按输入贡献散射，以独立合法origin集合生成输出位置；两者共享参数校验和零张量分配，故不构成对这些公共辅助逻辑的独立验证。三组用例覆盖分组、batch=2、stride、dilation及depthwise multiplier，另有手算[8,14,8]和空输出。忽略组索引及保持2×2输出shape但忽略dilation的故障均实际改变采样并被拒绝。padding检查用固定1/2参考拒绝源像素掩码和物理容量分母；独立滑窗参考及固定[1]、[1,1]、[2,2]轨迹拒绝仅末端屏蔽。1080个小域实例等于120种输入乘3种容量乘3组两层程序，验证声明范围内逐层隔离，包含带符号输入和bias。其余负对照实际检测BN漏mean、残差覆盖、逆映射漏偏移、猜测统一比例及NMS比较符号、裁剪顺序、类别合同错误。NMS固定保留集合与手算IoU提供外部期望；成本常量只支持算例算术核对。actual_preflight的remote_bwrap执行绑定脚本9a5ecd1812c4e5a8cd044cc55ab96ae573098e84edde73c5a665c99d476b65e6，返回码0、stderr为空、未超时，stdout包含上述OBS及DETECTED。作者说明自身阶段未运行，与后续提供的协调执行记录并不矛盾；本审阅未重跑，也未把正文提出但脚本未执行的设备、预处理或质量检查记为PASS。来源文本支持ResNet v1残差/固定BN/历史检测路线、TVM计算与schedule及intrinsic分离、数值文档的归约和批路径差异；正文将新增索引、成本及padding反例明确标为独立推导，未冒充来源实测。"
}
